11	// Used by archive, diff, and registry tests.
12	func buildTarGz(t *testing.T, files map[string]string) []byte {
13		t.Helper()
14		var buf bytes.Buffer
15		gz := gzip.NewWriter(&buf)
16		tw := tar.NewWriter(gz)
17		for name, body := range files {
18			hdr := &tar.Header{
19				Name: name,
20				Mode: 0o644,
21				Size: int64(len(body)),
22			}
23			if err := tw.WriteHeader(hdr); err != nil {
24				t.Fatalf("WriteHeader %s: %v", name, err)
25			}
26			if _, err := tw.Write([]byte(body)); err != nil {
27				t.Fatalf("Write %s: %v", name, err)
28			}
29		}
30		if err := tw.Close(); err != nil {
31			t.Fatal(err)
32		}
33		if err := gz.Close(); err != nil {
34			t.Fatal(err)
35		}
36		return buf.Bytes()
37	}
