39	func TestExtractHappyPath(t *testing.T) {
40		in := map[string]string{
41			"main.tf":      "resource \"aws_s3_bucket\" \"x\" {}\n",
42			"variables.tf": "variable \"name\" { type = string }\n",
43			"README.md":    "hello\n",
44		}
45		tgz := buildTarGz(t, in)
46	
47		mod, err := Extract(tgz, 1<<20)
48		if err != nil {
49			t.Fatalf("Extract: %v", err)
50		}
51		if len(mod.Files) != len(in) {
52			t.Fatalf("got %d files, want %d", len(mod.Files), len(in))
53		}
54		for name, want := range in {
55			got, ok := mod.Files[name]
56			if !ok {
57				t.Errorf("missing file: %s", name)
58				continue
59			}
60			if string(got) != want {
61				t.Errorf("%s body = %q, want %q", name, got, want)
62			}
63		}
64	}
